import { put, list } from "@vercel/blob";
import { blobToken, blobConfigured } from "./blob-token";

/**
 * Nearby events, cached per place.
 *
 * The list is generated by a model call that takes a couple of seconds and
 * costs money, which is why Home never showed one: running it on every visit
 * to draw a card nobody asked for is a bill and a wait. But a city's recurring
 * car events -- the Saturday Cars & Coffee, the August concours -- change on
 * the order of months, so the answer for a place is worth keeping.
 *
 * One object per place, like the credentials store and for the same reason:
 * Blob serves public URLs through a CDN with a 60-second floor on max-age and
 * ignores query strings, so a single document would hand back a stale copy for
 * a minute after every write. A place is its own path, and a new place is a
 * path nothing has fetched.
 */

export type CarEvent = {
  name: string;
  type: string;
  venue?: string;
  city: string;
  when: string;
  note?: string;
};

type Cached = { place: string; events: CarEvent[]; at: number };

/** Events for a city change over months, so a week is conservative. */
export const EVENTS_TTL_MS = 7 * 24 * 60 * 60 * 1000;

/** "Miami, Florida, United States" -> "miami-florida-united-states". */
export function placeSlug(place: string): string {
  return place
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
}

function pathFor(place: string): string {
  return `events/${placeSlug(place)}.json`;
}

export function eventsCacheConfigured(): boolean {
  return blobConfigured();
}

/** What is stored for this place, however old. Null when nothing is. */
export async function readEvents(place: string): Promise<Cached | null> {
  if (!blobConfigured() || !place.trim()) return null;
  const path = pathFor(place);
  try {
    const { blobs } = await list({ prefix: path, token: blobToken() });
    const url = blobs.find((b) => b.pathname === path)?.url;
    if (!url) return null;
    const res = await fetch(url, { cache: "no-store" });
    if (!res.ok) return null;
    const data = (await res.json()) as Partial<Cached>;
    const events = Array.isArray(data?.events) ? (data.events as CarEvent[]) : [];
    return events.length > 0
      ? { place: data.place || place, events, at: typeof data.at === "number" ? data.at : 0 }
      : null;
  } catch {
    return null;
  }
}

/** Best-effort: a storage failure must not fail a request that has an answer. */
export async function writeEvents(place: string, events: CarEvent[]): Promise<void> {
  if (!blobConfigured() || events.length === 0) return;
  try {
    await put(pathFor(place), JSON.stringify({ place, events, at: Date.now() } satisfies Cached), {
      access: "public",
      contentType: "application/json",
      allowOverwrite: true,
      addRandomSuffix: false,
      cacheControlMaxAge: 60,
      token: blobToken(),
    });
  } catch {
    /* the list is already on its way to the client */
  }
}

export const fresh = (at: number) => Date.now() - at < EVENTS_TTL_MS;
